    inputSchema: {"type":"object","properties":{"categoryRef":{"type":"string","minLength":1,"description":"Slug o id (uuid) de la categoría o subcategoría (ej: \"cevicherias\")."}},"required":["categoryRef"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"},
